  Future<ExpenseRow> addExpense({required ExpenseInput input}) => RustLib
      .instance
      .api
      .crateApiAppCompterAppAddExpense(that: this, input: input);

  Future<ProjectDetail> addMilestone({
    required String projectId,
    required MilestoneInput input,
  }) => RustLib.instance.api.crateApiAppCompterAppAddMilestone(
    that: this,
    projectId: projectId,
    input: input,
  );

  /// Check the lines picked for a credit note against invoice `number` before asking when and
  /// why: each amount is a number, more than zero and no more than is left on its line. A
  /// refusal names the line ([`InputField::CreditLine`], with its milestone as `line`).
  Future<void> checkCreditLines({
    required String number,
    required List<CreditLineInput> lines,
  }) => RustLib.instance.api.crateApiAppCompterAppCheckCreditLines(
    that: this,
    number: number,
    lines: lines,
  );

  /// One client with their projects and invoices
  Future<ClientDetail> client({required String id}) =>
      RustLib.instance.api.crateApiAppCompterAppClient(that: this, id: id);

  /// The Clients screen: every saved client with their projects counted and what they owe
  Future<List<ClientSummaryRow>> clientList() =>
      RustLib.instance.api.crateApiAppCompterAppClientList(that: this);

  /// The names of the open projects of `from` that merging it into `into` would give
  /// `into`'s details: asked about before [`merge_client`](Self::merge_client). A merge that
  /// would be refused is refused here.
  Future<List<String>> clientProjectsToMerge({
    required String from,
    required String into,
  }) => RustLib.instance.api.crateApiAppCompterAppClientProjectsToMerge(
    that: this,
    from: from,
    into: into,
  );

